simulate_genotype &lt;- function(p) {

  # simulate with sample function
  alleles &lt;- sample(c("A", "a"), 
              size = 2, 
              replace = TRUE, 
              prob = c(p, 1 - p))

  n_A &lt;- sum(alleles == "A")

  # if else statement
  if (n_A == 2) {
    "AA"
  } else if (n_A == 1) {
    "Aa"
  } else {
    "aa"
  }
}

simulate_genotype(0.6)
